function SkillBar({label,pct,onOpen}){const ref=useRef(null);useEffect(()=>{const el=ref.current;if(!el)return;let started=false;const obs=new IntersectionObserver(es=>{es.forEach(e=>{if(e.isIntersecting&&!started){started=true;el.classList.add('on');obs.disconnect()}})},{threshold:.3});obs.observe(el);return()=>obs.disconnect()},[]);return <div className="skill" role="button" tabIndex={0} onClick={onOpen} onKeyDown={e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();onOpen&&onOpen()}}}><div className="skill-top"><span>{label}</span><span className="skill-hint"><ArrowUpRight size={13}/></span><b>{pct}%</b></div><div className="skill-bar"><i ref={ref} style={{'--p':pct+'%'}}/></div></div>}
