function Modal({title,close,children,wide=false}){useEffect(()=>{const onKey=e=>{if(e.key==='Escape')close()};document.addEventListener('keydown',onKey);const prev=document.body.style.overflow;document.body.style.overflow='hidden';return()=>{document.removeEventListener('keydown',onKey);document.body.style.overflow=prev}},[close]);return <div className="overlay" onMouseDown={e=>e.target===e.currentTarget&&close()}><div className={'modal '+(wide?'wide':'')} role="dialog" aria-modal="true" aria-label={title}><div className="modal-head"><b>{title}</b><button onClick={close} aria-label="Close"><X/></button></div><div className="modal-body">{children}</div></div></div>}
