function TypingRole({roles}){const list=roles&&roles.length?roles:['Final-Year MBBS Student','Medical Content Writer'];const[index,setIndex]=useState(0),[text,setText]=useState(''),[deleting,setDeleting]=useState(false);useEffect(()=>{const word=list[index];let delay=deleting?38:72;if(!deleting&&text===word)delay=1500;if(deleting&&text==='')delay=280;const timer=setTimeout(()=>{if(!deleting){if(text.length<word.length)setText(word.slice(0,text.length+1));else setDeleting(true)}else{if(text.length>0)setText(text.slice(0,-1));else{setDeleting(false);setIndex((index+1)%list.length)}}},delay);return()=>clearTimeout(timer)},[text,deleting,index]);return <h2 className="hero-role"><span className="typed-text">{text}</span><span className="type-cursor" aria-hidden="true"/></h2>}
