 const load=()=>api('/content').then(setData).catch(e=>notify(e.message));useEffect(()=>{load()},[]);useEffect(()=>{if(data?.site?.meta?.title)document.title=data.site.meta.title},[data]);useEffect(()=>{document.documentElement.dataset.theme=theme;localStorage.setItem('na-theme',theme)},[theme]);
